 const chunks=withoutMarks.split(/\s+\/\s+(?=سوال\s*نمبر)/);
 if(chunks.length!==2)return null;
 const english=chunks[0].replace(/^\s*Q\s*\d+\s*[.:)]?\s*/i,'').trim();
