 if(/^\|\s*English\s*\|\s*اردو\s*\|/i.test(lines[0]||''))return 'MCQ';
 if(lines.length>=2&&lines.every(x=>/^\d+[.)]\s+.+?\s+\/\s+.+$/.test(x)))return 'Short';
 if(lines.length===3&&/^\(A\)\s+.+\s+\/\s+.+$/.test(lines[0])&&
   /^OR\s*\/\s*یا$/i.test(lines[1])&&/^\(B\)\s+.+\s+\/\s+.+$/.test(lines[2]))return 'Long';
